'use client'

import { useCallback, useMemo, useState } from 'react'
import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import { subDays, startOfDay, endOfDay, format } from 'date-fns'
import { Download } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Switch } from '@/components/ui/switch'
import { Label } from '@/components/ui/label'
import { DateRangePicker } from '@/components/ui/date-range-picker'
import type { DateRange } from '@/components/ui/date-range-picker'
import { useAnalyticsExport } from '@/components/reports/AnalyticsExportProvider'
import { cn } from '@/lib/utils'

function buildDefaultRange(): DateRange {
  const today = new Date()
  return {
    from: startOfDay(subDays(today, 29)),
    to: endOfDay(today),
  }
}

/**
 * Convert a Date into an ISO 8601 string with timezone offset.
 * Backend route schemas validate with z.string().datetime({ offset: true })
 * which REJECTS plain "YYYY-MM-DD" strings. Always emit a full ISO with TZ.
 * `from` snaps to start-of-day, `to` snaps to end-of-day to capture the
 * full inclusive day boundary on the server.
 */
function toFromParam(d: Date): string {
  return startOfDay(d).toISOString()
}

function toToParam(d: Date): string {
  return endOfDay(d).toISOString()
}

function rangeLabel(range: DateRange): string {
  const from = range.from ? format(range.from, 'yyyy-MM-dd') : 'na'
  const to = range.to ? format(range.to, 'yyyy-MM-dd') : 'na'
  return `${from}_${to}`
}

/**
 * Global analytics toolbar — mounts in the reports layout above page content.
 * Controls:
 *   DateRangePicker → writes ?from=<ISO>&to=<ISO> (full ISO 8601 with offset)
 *   Compare toggle  → writes ?compare=1 / removes when off
 *   Export CSV      → calls registered tab serializer via AnalyticsExportProvider
 */
export function AnalyticsToolbar({ className }: { className?: string }) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const { invoke } = useAnalyticsExport()
  const [exporting, setExporting] = useState(false)

  // Derive current range from URL params, fall back to last-30d.
  // Memoised so the export callback doesn't re-create on every render.
  const fromParam = searchParams.get('from')
  const toParam_ = searchParams.get('to')
  const compareParam = searchParams.get('compare') === '1'

  const currentRange: DateRange = useMemo(() => {
    const fallback = buildDefaultRange()
    return {
      from: fromParam ? new Date(fromParam) : fallback.from,
      to: toParam_ ? new Date(toParam_) : fallback.to,
    }
  }, [fromParam, toParam_])

  function handleRangeChange(range: DateRange) {
    if (!range.from || !range.to) return
    const params = new URLSearchParams(searchParams.toString())
    params.set('from', toFromParam(range.from))
    params.set('to', toToParam(range.to))
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  function handleCompareToggle(checked: boolean) {
    const params = new URLSearchParams(searchParams.toString())
    if (checked) {
      params.set('compare', '1')
    } else {
      params.delete('compare')
    }
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  const handleExport = useCallback(async () => {
    setExporting(true)
    try {
      await invoke(pathname, rangeLabel(currentRange))
    } finally {
      setExporting(false)
    }
  }, [invoke, pathname, currentRange])

  return (
    <div
      className={cn(
        // Sticky on scroll, bone background, hairline bottom border
        'sticky top-0 z-20 bg-[var(--color-bone)] border-b border-[var(--color-border)]',
        'py-3 px-0',
        className,
      )}
    >
      {/* Inner row — responsive stack */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-end">
        {/* Compare toggle */}
        <div className="flex items-center gap-2">
          <Switch
            id="analytics-compare"
            checked={compareParam}
            onCheckedChange={handleCompareToggle}
          />
          <Label
            htmlFor="analytics-compare"
            className="text-sm text-[var(--color-stone)] cursor-pointer select-none"
          >
            Compare to prior period
          </Label>
        </div>

        {/* Date range picker */}
        <DateRangePicker
          value={currentRange}
          onValueChange={handleRangeChange}
          className="w-full sm:w-auto font-[tabular-nums]"
        />

        {/* Export CSV */}
        <Button
          size="sm"
          variant="outline"
          onClick={handleExport}
          disabled={exporting}
          className="shrink-0 border-[var(--color-border)] text-[var(--color-onyx)] hover:bg-[var(--color-onyx)] hover:text-[var(--color-bone)] transition-colors"
        >
          <Download className="mr-2 size-3.5" aria-hidden="true" />
          {exporting ? 'Exporting…' : 'Export CSV'}
        </Button>
      </div>
    </div>
  )
}
