'use client'

import { useEffect, useRef } from 'react'
import { usePathname } from 'next/navigation'
import { useAnalyticsExport } from '@/components/reports/AnalyticsExportProvider'
import { exportRows } from '@/lib/csv-export'

interface UseExportCsvOptions<T extends Record<string, unknown>> {
  /** Filename stem — no extension, no path. Date range appended by toolbar. */
  filename: string
  /** Called on export. Must return rows synchronously or a Promise. */
  getRows: () => T[] | Promise<T[]>
  /** Optional column header display overrides. */
  headers?: Partial<Record<keyof T, string>>
}

/**
 * Register a CSV serializer for the current page with the global AnalyticsToolbar.
 * Auto-registers on mount, deregisters on unmount.
 *
 * Stale-closure protection: the serializer reads from refs that are kept in sync
 * with the latest opts on every render. Without this, a serializer registered
 * once would forever see the first render's `getRows` (closing over the first
 * render's `data`) — exporting stale rows after URL/sort/compare changes.
 */
export function useExportCsv<T extends Record<string, unknown>>(
  opts: UseExportCsvOptions<T>,
): void {
  const pathname = usePathname()
  const { register, unregister } = useAnalyticsExport()

  // Latest-ref pattern: keep the most recent options accessible to the
  // registered serializer without forcing a re-register on each render.
  const getRowsRef = useRef(opts.getRows)
  const filenameRef = useRef(opts.filename)
  const headersRef = useRef(opts.headers)

  // Sync refs with the latest values on every render (including after sort/data changes).
  getRowsRef.current = opts.getRows
  filenameRef.current = opts.filename
  headersRef.current = opts.headers

  useEffect(() => {
    const serializer = async (rangeLabel: string) => {
      const rows = await getRowsRef.current()
      if (rows.length === 0) return
      exportRows({
        filename: `${filenameRef.current}-${rangeLabel}`,
        rows,
        headers: headersRef.current as Partial<Record<keyof T, string>>,
      })
    }

    register(pathname, serializer)
    return () => unregister(pathname)
  }, [pathname, register, unregister])
}
